import * as fs from "node:fs";
import * as path from "node:path";

/**
 * What the release job knew about this build, read from `bundle/` at the
 * package root. The files there are generated by CI (build.yml) and packed
 * into the executable by `pkg`; a local build has none of them, and every
 * caller copes with that.
 *
 *   bundle/build-info.json      {"tag": "dev-v0.5.0", "commit": "<sha>"}
 *   bundle/compatibility.json   the published compatibility.json at build time
 *
 * The tag matters because a version alone is ambiguous: `v0.5.0` and
 * `dev-v0.5.0` both report 0.5.0, and compatibility.json may give them
 * different floors.
 */

export interface BuildInfo {
  tag: string | null;
  commit: string | null;
}

/** `<package root>/bundle`, from both `src/utils` (ts-node) and `dist/utils`. */
export function bundleDir(): string {
  return path.join(__dirname, "..", "..", "bundle");
}

let cached: BuildInfo | null = null;

export function buildInfo(): BuildInfo {
  if (cached) return cached;
  let info: BuildInfo = { tag: null, commit: null };
  try {
    const raw = JSON.parse(fs.readFileSync(path.join(bundleDir(), "build-info.json"), "utf8")) as Record<
      string,
      unknown
    >;
    info = {
      tag: typeof raw.tag === "string" && raw.tag.trim() ? raw.tag.trim() : null,
      commit: typeof raw.commit === "string" && raw.commit.trim() ? raw.commit.trim() : null,
    };
  } catch {
    // a local build: no release tag known
  }
  cached = info;
  return info;
}

/** Path of the compatibility.json bundled at build time, or null when there is none. */
export function bundledCompatibilityFile(): string | null {
  const file = path.join(bundleDir(), "compatibility.json");
  try {
    return fs.statSync(file).isFile() ? file : null;
  } catch {
    return null;
  }
}
